int arr[5] = {1, 2, 3, 4, 5};
int* p = arr;

// Pointer Arithmetic: Offset
int val_3rd = *(p + 2); // Access arr[2] (value 3)

// Pointer Arithmetic: Increment
p++;                    // p now points to arr[1]
int val_2nd = *p;       // value 2

// Pointer Arithmetic: Difference
int* end_ptr = arr + 5;
ptrdiff_t count = end_ptr - arr; // count = 5

// Subtraction returns number of elements, not bytes

