int value = 100;
int* ptr1 = &value;         // Pointer to int

// Pointer to a Pointer (Level 2)
int** ptr2 = &ptr1;         // Pointer to int*

// Accessing value through Level 2
int data = **ptr2;          // data = 100

// Modifying Level 1 pointer via Level 2
int newValue = 200;
*ptr2 = &newValue;          // ptr1 now points to newValue

// Level 1 access changed
data = *ptr1;               // data = 200

