typedef struct { int id; char flag; } Record;
char raw_data[sizeof(Record)];

// Type Punning via Casting (char* to struct*)
Record* rec_ptr = (Record*)raw_data;
rec_ptr->id = 404;

// Byte-level view using unsigned char*
unsigned char* byte_ptr = (unsigned char*)raw_data;
byte_ptr++; // Move 1 byte past the start
unsigned char byte = *byte_ptr;

// Use of void* for generic storage
void* generic_ptr = rec_ptr;
// Cast back required for access
((Record*)generic_ptr)->flag = 'X';
